import{c as r,Q as o,j as a,m as s}from"./chunks/framework.rWdQudnF.js";const p=JSON.parse('{"title":"DSSA-特定领域软件架构","description":"","frontmatter":{"title":"DSSA-特定领域软件架构"},"headers":[],"relativePath":"综合知识/架构设计/架构设计方法/特定领域软件架构.md","filePath":"综合知识/架构设计/架构设计方法/特定领域软件架构.md","lastUpdated":null}'),d={name:"综合知识/架构设计/架构设计方法/特定领域软件架构.md"};function n(e,t,l,i,h,g){return o(),a("div",null,[...t[0]||(t[0]=[s('<blockquote><p>DSSA 是特定领域中<strong>一组应用的标准软件架构</strong>，三步法和四角色是高频考点。</p></blockquote><p>DSSA就是专用于一类特定类型的任务（领域）的、在整个领域中能有效地使用的、为成功构造应用系统限定了标准的组合结构的软件构件的集合。 DSSA就是一个特定的问题领域中支持一组应用的领域模型、参考需求、参考架构等组成的开发基础，其目标就是<strong>支持在一个特定领域中多个应用的生成</strong>。</p><ul><li>垂直域：在一个特定领域中的通用的软件架构，是一个完整的架构。</li><li>水平域：在多个不同的特定领域之间的相同的部分的小工具（如购物和教育都有收费系统，收费系统即是水平域)。</li></ul><h3 id="dssa-三步法" tabindex="-1">DSSA 三步法 <a class="header-anchor" href="#dssa-三步法" aria-label="Permalink to &quot;DSSA 三步法&quot;">​</a></h3><p>DSSA 的三个基本活动</p><table tabindex="0"><thead><tr><th>阶段</th><th>目标</th><th>产出</th><th>主要活动</th></tr></thead><tbody><tr><td><strong>领域分析</strong></td><td>获得<strong>领域模型</strong></td><td>领域模型</td><td>分析共性需求</td></tr><tr><td><strong>领域设计</strong></td><td>获得<strong>DSSA</strong></td><td>领域架构</td><td>高层次设计解决方案</td></tr><tr><td><strong>领域实现</strong></td><td>开发和组织<strong>可重用信息</strong></td><td>可重用构件/资产</td><td>实现可重用资产</td></tr></tbody></table><blockquote><p>⚠️ 领域设计的主要目标是<strong>获得 DSSA</strong>（不是领域模型）。建立过程是<strong>螺旋模型</strong>。</p></blockquote><h3 id="四类参与角色" tabindex="-1">四类参与角色 <a class="header-anchor" href="#四类参与角色" aria-label="Permalink to &quot;四类参与角色&quot;">​</a></h3><p>参与 DSSA 的四种角色人员</p><table tabindex="0"><thead><tr><th>角色</th><th>职责</th></tr></thead><tbody><tr><td><strong>领域专家</strong></td><td>提供领域知识、需求规约和实现知识</td></tr><tr><td><strong>领域分析者</strong></td><td>控制领域分析过程，组织领域模型</td></tr><tr><td><strong>领域设计者</strong></td><td>开发领域设计，验证准确性和一致性</td></tr><tr><td><strong>领域实现者</strong></td><td>实现可重用资产</td></tr></tbody></table><blockquote><p>⚠️ 最适合担任领域分析师的是：<strong>具有知识工程背景的有经验的系统分析员</strong></p></blockquote><h3 id="垂直域-vs-水平域" tabindex="-1">垂直域 vs 水平域 <a class="header-anchor" href="#垂直域-vs-水平域" aria-label="Permalink to &quot;垂直域 vs 水平域&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>定义</th><th>范围</th></tr></thead><tbody><tr><td><strong>垂直域</strong></td><td>特定的<strong>系统族</strong>，包含整个系统族内的多个系统</td><td>整个系统族</td></tr><tr><td><strong>水平域</strong></td><td>多个系统族中功能区域的<strong>共有部分</strong></td><td>子系统级</td></tr></tbody></table><h3 id="dssa-特征" tabindex="-1">DSSA 特征 <a class="header-anchor" href="#dssa-特征" aria-label="Permalink to &quot;DSSA 特征&quot;">​</a></h3><ol><li>严格定义的问题域和解决域</li><li>具有<strong>普遍性</strong></li><li>对领域有合适程度的抽象</li><li>具备固定典型开发过程中的<strong>可重用元素</strong></li></ol><blockquote><p>⚠️ &quot;随机性&quot; 不属于 DSSA 特征。</p></blockquote><h3 id="建立dssa的过程" tabindex="-1">建立DSSA的过程 <a class="header-anchor" href="#建立dssa的过程" aria-label="Permalink to &quot;建立DSSA的过程&quot;">​</a></h3><ul><li>(1)定义领域范围：领域中的应用要满足用户一系列的需求。</li><li>(2)定义领域特定的元素：<strong>建立领域的字典，归纳领域中的术语</strong>，识别出领域中相同和不相同的元素。</li><li>(3)定义领域特定的设计和实现需求的<strong>约束</strong>：识别领域中的所有约束，这些约束对领域的设计和实现会造成什么后果。</li><li>(4)定义<strong>领域模型和架构</strong>：产生一般的架构，并描述其构件说明。</li><li>(5)产生、搜集可复用的产品单元：为DSSA增加复用构件，使可用于新的系统：</li></ul><p>以上过程是<strong>并发的、递归的、反复的、螺旋型的</strong>。该过程的目的是将用户的需求映射为基于实现限制集合的软件需求，这些需求定义了DSSA。</p><h3 id="dssa的三层次系统模型" tabindex="-1">DSSA的三层次系统模型 <a class="header-anchor" href="#dssa的三层次系统模型" aria-label="Permalink to &quot;DSSA的三层次系统模型&quot;">​</a></h3><p>领域开发环境：<strong>领域架构师决定核心架构</strong>，产出参考结构、参考需求、架构、领域模型、开发工具。</p><p>领域特定的应用开发环境：应用工程师根据具体环境来将核心架构实例化。</p><p>应用执行环境：操作员实现实例化后的架构。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517144433.png" alt="image.png"></p>',24)])])}const c=r(d,[["render",n]]);export{p as __pageData,c as default};
